message.content:
{
  "description": "The creature is shown in right-facing profile standing on a plain off-white background. It has the overall body shape, fur, head and limbs of a brown bear, but its dorsal surface from the top of the head to the tip of the tail is covered by a continuous, glossy, dark brown to black segmented covering that looks like a crustacean exoskeleton. The bear's brown fur is visible on the head, muzzle, underside, legs and tail tip, with a lighter tan on the muzzle and around the eyes. A single long, black, smooth, tapering horn curves up and back from the top of the head covering. The animal stands on four thick, furry legs ending in broad clawed paws, and has a short tail that is armored on top and tufted with fur at the tip.",
  "parts": [
    {
      "part": "head",
      "looks_like": "bear-like, with dense brown fur, a lighter tan muzzle, a large black nose, small brown eyes, and white whiskers; the top and sides are covered by a dark glossy helmet-like plate",
      "where": "at the front right of the body, facing right"
    },
    {
      "part": "horns",
      "looks_like": "one long, black, glossy, smooth, sharply tapering horn that curves upward and backward from the head and then arches forward to a point",
      "where": "arising from the center top of the head plate, extending above the back"
    },
    {
      "part": "ears",
      "looks_like": "two small, rounded, furry brown ears with dense fur",
      "where": "on the top sides of the head, protruding through openings in the head plate on either side of the horn base"
    },
    {
      "part": "legs",
      "looks_like": "four thick, columnar, densely furry brown legs, two forelegs and two hindlegs",
      "where": "under the body, supporting it; forelegs under the chest, hindlegs under the hips"
    },
    {
      "part": "feet",
      "looks_like": "four broad furry paws with long, dark, curved claws visible on each toe",
      "where": "at the bottom of each leg, in contact with the ground"
    },
    {
      "part": "tail",
      "looks_like": "short, with dark glossy segmented plates on the dorsal side continuing from the back and a tuft of brown fur at the very tip, hanging downward",
      "where": "at the rear left end of the body"
    },
    {
      "part": "plates",
      "looks_like": "extensive dark brown-black glossy segmented armor forming overlapping transverse bands across the back from neck to tail, with larger smooth shoulder and hip shields, a series of small circular holes along the lower edge of the back bands, and a lateral row of oval openings on the furry side; the plates also form a helmet over the head, rings around the neck, and a covering over the tail",
      "where": "covering the dorsal and lateral surfaces of the head, neck, back, sides, shoulders, hips and tail, sitting over the brown fur"
    }
  ],
  "attached_objects": [],
  "animals": ["bear", "pill bug"],
  "separate_bodies": 1,
  "heads": 1,
  "walking_legs": 4,
  "wings": 0,
  "extra_limb_pieces": 0,
  "tails": 1
}
